import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import type { HTMLAttributes } from "react";
import {
  CheckboxGroup as AriaCheckboxGroup,
  type CheckboxGroupProps,
  FieldError,
  Label,
  Text,
} from "react-aria-components";
import { cn } from "./utils";

export function CheckboxGroup({
  className,
  label,
  description,
  children,
  ...props
}: Omit<CheckboxGroupProps, "children"> &
  React.RefAttributes<HTMLDivElement> & {
    label?: string;
    description?: string;
    children: React.ReactNode;
  }) {
  return (
    <AriaCheckboxGroup
      {...props}
      data-slot="checkbox-group"
      className={cn("grid gap-1", className)}
    >
      {label === undefined ? (
        children
      ) : (
        <>
          <CheckboxGroupLabel>{label}</CheckboxGroupLabel>
          {description && (
            <CheckboxGroupDescription>{description}</CheckboxGroupDescription>
          )}
          <CheckboxGroupItems>{children}</CheckboxGroupItems>
          <CheckboxGroupError />
        </>
      )}
    </AriaCheckboxGroup>
  );
}

export function CheckboxGroupLabel({
  className,
  ...props
}: React.ComponentProps<typeof Label>) {
  return (
    <Label
      {...props}
      data-slot="checkbox-group-label"
      className={cn("text-sm font-semibold text-foreground", className)}
    />
  );
}

export function CheckboxGroupItems({
  className,
  ...props
}: HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      {...props}
      data-slot="checkbox-group-items"
      className={cn("grid gap-1 pt-1", className)}
    />
  );
}

export function CheckboxGroupDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="checkbox-group-description"
      className={cn("text-xs leading-5 text-muted-foreground", className)}
    />
  );
}

export function CheckboxGroupError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="checkbox-group-error"
      className={cn("text-xs text-destructive", className)}
    />
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { createContext, useContext, useState } from "react";
import {
  Checkbox as AriaCheckbox,
  type CheckboxProps as AriaCheckboxProps,
  composeRenderProps,
} from "react-aria-components";
import { Check, Minus } from "reicon-react";
import { cn } from "./utils";

const CheckboxStateContext = createContext({
  isSelected: false,
  isIndeterminate: false,
});

export interface CheckboxProps
  extends Omit<AriaCheckboxProps, "className" | "children"> {
  ref?: React.Ref<HTMLLabelElement>;
  className?: AriaCheckboxProps["className"];
  description?: string;
  children?: AriaCheckboxProps["children"];
  checked?: boolean | "indeterminate";
  defaultChecked?: boolean | "indeterminate";
  onCheckedChange?: (checked: boolean) => void;
}

export function Checkbox({
  children,
  description,
  className,
  checked,
  defaultChecked,
  onCheckedChange,
  ...props
}: CheckboxProps) {
  const [initialIndeterminate, setInitialIndeterminate] = useState(
    defaultChecked === "indeterminate",
  );
  return (
    <AriaCheckbox
      {...props}
      isSelected={checked === undefined ? props.isSelected : checked === true}
      defaultSelected={
        defaultChecked === undefined
          ? props.defaultSelected
          : defaultChecked === true
      }
      isIndeterminate={
        checked === undefined
          ? initialIndeterminate || props.isIndeterminate
          : checked === "indeterminate"
      }
      onChange={(value) => {
        setInitialIndeterminate(false);
        props.onChange?.(value);
        onCheckedChange?.(value);
      }}
      data-slot="checkbox"
      className={composeRenderProps(className, (className) =>
        cn(
          "group inline-flex min-h-11 cursor-pointer items-start gap-3 rounded-md text-sm text-foreground data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-2 data-[focus-visible]:outline-ring",
          typeof children === "string" && !description && "items-center",
          className,
        ),
      )}
    >
      {(state) => (
        <CheckboxStateContext.Provider value={state}>
          {typeof children === "function" ? (
            children(state)
          ) : typeof children === "string" || children == null ? (
            <>
              <CheckboxIndicator />
              {(children || description) && (
                <span className="pt-0.5">
                  {children && (
                    <span className="block font-medium">{children}</span>
                  )}
                  {description && (
                    <span className="mt-1 block text-xs leading-5 text-muted-foreground">
                      {description}
                    </span>
                  )}
                </span>
              )}
            </>
          ) : (
            children
          )}
        </CheckboxStateContext.Provider>
      )}
    </AriaCheckbox>
  );
}

export function CheckboxIndicator({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  const { isSelected, isIndeterminate } = useContext(CheckboxStateContext);
  const reduceMotion = useReducedMotion();
  const isChecked = isSelected || isIndeterminate;
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="checkbox-indicator"
      className={cn(
        "mt-0.5 grid size-5 shrink-0 place-items-center rounded-md border border-input bg-card shadow-[var(--shadow-inset)] group-hover:border-primary/60 group-data-[selected]:border-primary group-data-[selected]:bg-primary group-data-[indeterminate]:border-primary group-data-[indeterminate]:bg-primary motion-safe:transition-[border-color,background-color] motion-safe:duration-150",
        className,
      )}
    >
      <motion.span
        initial={false}
        animate={{
          scale: isChecked ? 1 : 0.86,
          opacity: isChecked ? 1 : 0,
        }}
        transition={{
          duration: reduceMotion ? 0 : 0.16,
          ease: [0.23, 1, 0.32, 1],
        }}
        className="text-primary-foreground"
      >
        {isIndeterminate ? (
          <Minus size={13} strokeWidth={2.5} />
        ) : (
          <Check size={13} strokeWidth={2.5} />
        )}
      </motion.span>
    </span>
  );
}

export function CheckboxLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="checkbox-label"
      className={cn("block font-medium", className)}
    />
  );
}

export function CheckboxDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="checkbox-description"
      className={cn(
        "mt-1 block text-xs leading-5 text-muted-foreground",
        className,
      )}
    />
  );
}
